//! Compares each ported module with the Python reference in tests/golden/ (generated by
//! tests/gen_golden.py from backend/audio_processor.py). Blocks are 480 samples, as in Python.

use hushcore_engine::dsp::compressor::DynamicsCompressor;
use hushcore_engine::dsp::deesser::DeEsser;
use hushcore_engine::dsp::eq::Equalizer3Band;
use hushcore_engine::dsp::exciter::Exciter;
use hushcore_engine::dsp::gate::NoiseGate;
use hushcore_engine::dsp::limiter::Limiter;
use serde_json::Value;
use std::path::PathBuf;

const SR: f64 = 48_000.0;

fn golden_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests").join("golden")
}

fn read_f32(name: &str) -> Vec<f32> {
    let path = golden_dir().join(name);
    let bytes = std::fs::read(&path).unwrap_or_else(|e| panic!("reading {}: {e}", path.display()));
    assert_eq!(bytes.len() % 4, 0, "{name} is not a whole number of f32 samples");
    bytes.chunks_exact(4).map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect()
}

fn manifest() -> Value {
    let text = std::fs::read_to_string(golden_dir().join("manifest.json")).expect("manifest.json");
    serde_json::from_str(&text).expect("manifest.json is valid JSON")
}

fn param(p: &Value, key: &str) -> f64 {
    p[key].as_f64().unwrap_or_else(|| panic!("manifest param {key} missing"))
}

/// Runs the module named in the manifest over `input`, in 480-sample blocks.
fn run_module(case: &Value, input: &[f32], block: usize) -> Vec<f32> {
    let p = &case["params"];
    let mut out = input.to_vec();
    match case["module"].as_str().unwrap() {
        "eq" => {
            let mut eq = Equalizer3Band::new(SR);
            eq.set_gains(param(p, "low_gain_db"), param(p, "mid_gain_db"), param(p, "high_gain_db"));
            for b in out.chunks_mut(block) {
                eq.process(b);
            }
        }
        "compressor" => {
            let mut c = DynamicsCompressor::new(SR);
            c.configure(
                param(p, "threshold_db"),
                param(p, "ratio"),
                param(p, "attack_ms"),
                param(p, "release_ms"),
            );
            for b in out.chunks_mut(block) {
                c.process(b);
            }
        }
        "gate" => {
            let mut g = NoiseGate::new(SR);
            for b in out.chunks_mut(block) {
                g.process(b, param(p, "threshold_db"), param(p, "release_ms"));
            }
        }
        "deesser" => {
            let mut d = DeEsser::new(SR);
            d.configure(param(p, "threshold_db"), param(p, "amount"));
            for b in out.chunks_mut(block) {
                d.process(b);
            }
        }
        "exciter" => {
            let mut e = Exciter::new(SR);
            e.configure(param(p, "frequency"), param(p, "amount"), param(p, "mix"));
            for b in out.chunks_mut(block) {
                e.process(b);
            }
        }
        "limiter" => {
            let mut l = Limiter::new(SR, 100.0);
            let thr = 10f64.powf(param(p, "threshold_db") / 20.0);
            for b in out.chunks_mut(block) {
                l.process(b, thr);
            }
        }
        other => panic!("unknown module {other} in manifest"),
    }
    out
}

#[test]
fn modules_match_python_reference() {
    let m = manifest();
    assert_eq!(m["sample_rate"].as_f64().unwrap(), SR);
    let block = m["block_size"].as_u64().unwrap() as usize;
    let cases = m["cases"].as_array().expect("cases");
    assert!(!cases.is_empty());

    for case in cases {
        let name = case["name"].as_str().unwrap();
        let tol = case["max_abs_tolerance"].as_f64().unwrap() as f32;
        let input = read_f32(case["input"].as_str().unwrap());
        let expected = read_f32(case["expected"].as_str().unwrap());
        assert_eq!(input.len(), expected.len(), "{name}: length mismatch");

        let got = run_module(case, &input, block);
        assert!(got.iter().all(|v| v.is_finite()), "{name}: non-finite output");

        let max_err = got.iter().zip(&expected).map(|(a, b)| (a - b).abs()).fold(0.0f32, f32::max);
        // The module must actually change the signal, otherwise the comparison proves nothing.
        let effect = got.iter().zip(&input).map(|(a, b)| (a - b).abs()).fold(0.0f32, f32::max);
        assert!(effect > 1e-3, "{name}: module output equals its input; the case does not exercise it");

        assert!(
            max_err <= tol,
            "{name}: max abs error {max_err:e} exceeds tolerance {tol:e} against the Python reference"
        );
        eprintln!("{name}: max abs error vs Python = {max_err:.3e} (tolerance {tol:.0e})");
    }
}
